import sys

def solve(n, k, rooms):
    free_rooms = [i for i in range(n) if rooms[i] == '0']

    if len(free_rooms) == k + 1:
        return 0

    left, right = 0, free_rooms[-1] - free_rooms[0]
    while left <= right:
        mid = (left + right) // 2
        if is_possible(free_rooms, k + 1, mid):
            right = mid - 1
        else:
            left = mid + 1

    return left

def is_possible(free_rooms, k, min_distance):
    count = 1
    last = free_rooms[0]
    for room in free_rooms[1:]:
        if room - last >= min_distance:
            count += 1
            last = room
        if count >= k:
            return True
    return False

if __name__ == "__main__":
    n, k = map(int, input().split())
    rooms = input().strip()
    print(solve(n, k, rooms))
